changeSet.sql:
INSERT INTO scenario (id, name, game_id, topic_id, starting_stage_id) SELECT q.id, CONCAT('FOF question ', q.id), m.game_id, c.topic_id, NULL FROM fof_question m JOIN question q ON q.id = m.question_id JOIN concept c ON c.id = q.concept_id WHERE m.game_id = 10 AND c.topic_id = 104;
INSERT INTO stage (id, scenario_id, question_id) SELECT s.id, s.id, m.question_id FROM scenario s JOIN fof_question m ON m.question_id = s.id AND m.game_id = s.game_id WHERE s.game_id = 10 AND s.topic_id = 104;
UPDATE scenario SET starting_stage_id = id WHERE game_id = 10 AND topic_id = 104 AND id IN (SELECT question_id FROM fof_question WHERE game_id = 10);
UPDATE answer SET terminal_resolution = CASE WHEN correct THEN 'POSITIVE' ELSE 'NEGATIVE' END WHERE question_id IN ( SELECT st.question_id FROM stage st JOIN scenario s ON s.id = st.scenario_id JOIN fof_question m ON m.question_id = st.question_id AND m.game_id = s.game_id WHERE s.game_id = 10 AND s.topic_id = 104 );
